from typing import List


class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp[parity][alternating_sum] = maximum reachable product
        # parity is the selected subsequence length modulo 2.
        dp = [{}, {}]

        for x in nums:
            old_even = dp[0].copy()
            old_odd = dp[1].copy()

            # Start a new subsequence containing only x.
            if x <= limit:
                if x > dp[1].get(x, -1):
                    dp[1][x] = x

            # Append x to every subsequence formed before this element.
            for parity, states in enumerate((old_even, old_odd)):
                next_parity = 1 - parity
                contribution_sign = 1 if parity == 0 else -1

                for alternating_sum, product in states.items():
                    new_sum = alternating_sum + contribution_sign * x
                    new_product = product * x

                    # Product zero must be retained; positive products above
                    # the limit cannot be used in any valid continuation.
                    if new_product <= limit:
                        if new_product > dp[next_parity].get(new_sum, -1):
                            dp[next_parity][new_sum] = new_product

        answer = max(dp[0].get(k, -1), dp[1].get(k, -1))
        return answer

import sys
from bisect import bisect_right

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    q = data[0]
    queries = data[1:1 + q]

    limit = 1_000_000

    is_prime = bytearray(b"\x01") * (limit + 1)
    is_prime[0] = 0
    is_prime[1] = 0

    r = int(limit ** 0.5)
    for i in range(2, r + 1):
        if is_prime[i]:
            start = i * i
            is_prime[start:limit + 1:i] = b"\x00" * (
                (limit - start) // i + 1
            )

    distinct_count = bytearray(limit + 1)
    for p in range(2, limit + 1):
        if is_prime[p]:
            for multiple in range(p, limit + 1, p):
                distinct_count[multiple] += 1

    candidates = [
        x * x
        for x in range(2, limit + 1)
        if distinct_count[x] == 2
    ]

    answers = []
    for a in queries:
        pos = bisect_right(candidates, a) - 1
        answers.append(str(candidates[pos]))

    sys.stdout.write("\n".join(answers))

if __name__ == "__main__":
    solve()

import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    t = next(it)
    answers = []

    for _ in range(t):
        n = next(it)
        k = next(it)
        length = 2 * k

        values = []
        best = []
        arg = []

        for i in range(n):
            x = next(it)
            y = next(it)
            z = next(it)
            v = (x, y, z)

            c = 0
            if y > v[c]:
                c = 1
            if z > v[c]:
                c = 2

            values.append(v)
            best.append(v[c])
            arg.append(c)

        order = sorted(range(n), key=lambda i: best[i], reverse=True)
        selected = [False] * n
        for i in order[:length]:
            selected[i] = True

        boundary = order[length - 1]
        base_sum = sum(best[i] for i in order[:length])

        parity = 0
        for i in order[:length]:
            parity ^= 1 << arg[i]

        selected_lists = [[], [], []]
        unselected_lists = [[], [], []]

        for i in range(n):
            c = arg[i]
            if selected[i]:
                selected_lists[c].append((best[i], i))
            else:
                unselected_lists[c].append((best[i], i))

        for c in range(3):
            selected_lists[c].sort()
            unselected_lists[c].sort(reverse=True)

        if parity == 0:
            answer = base_sum
        else:
            answer = -1

            odd = [c for c in range(3) if (parity >> c) & 1]
            r, s = odd

            # No reassignment: exchange one selected cake and one
            # unselected cake between the two odd coordinate classes.
            for from_c, to_c in ((r, s), (s, r)):
                if selected_lists[from_c] and unselected_lists[to_c]:
                    take = selected_lists[from_c][0][0]
                    give = unselected_lists[to_c][0][0]
                    answer = max(answer, base_sum - take + give)

            def selected_min(c, mandatory, outside_i, removed):
                candidates = []

                for value, idx in selected_lists[c][:3]:
                    if idx != mandatory and idx != removed:
                        candidates.append(value)

                if outside_i is not None and arg[outside_i] == c:
                    candidates.append(best[outside_i])

                return min(candidates) if candidates else None

            def unselected_max(c, outside_i, removed):
                candidates = []

                for value, idx in unselected_lists[c][:3]:
                    if idx != outside_i:
                        candidates.append(value)

                if outside_i is not None and removed is not None:
                    if arg[removed] == c:
                        candidates.append(best[removed])

                return max(candidates) if candidates else None

            for i in range(n):
                a = arg[i]

                if selected[i]:
                    outside_i = None
                    removed = None
                    subset_sum = base_sum
                    subset_parity = parity
                else:
                    outside_i = i
                    removed = boundary
                    subset_sum = base_sum - best[boundary] + best[i]
                    subset_parity = parity ^ (1 << arg[removed]) ^ (1 << arg[outside_i])

                for b in range(3):
                    if b == a:
                        continue

                    target_parity = (1 << a) | (1 << b)
                    mismatch = subset_parity ^ target_parity
                    reassignment_loss = best[i] - values[i][b]

                    if mismatch == 0:
                        answer = max(answer, subset_sum - reassignment_loss)
                        continue

                    bits = [c for c in range(3) if (mismatch >> c) & 1]
                    if len(bits) != 2:
                        continue

                    r, s = bits
                    for from_c, to_c in ((r, s), (s, r)):
                        take = selected_min(from_c, i, outside_i, removed)
                        give = unselected_max(to_c, outside_i, removed)

                        if take is not None and give is not None:
                            candidate = (
                                subset_sum
                                - take
                                + give
                                - reassignment_loss
                            )
                            answer = max(answer, candidate)

        answers.append(str(answer))

    sys.stdout.write("\n".join(answers))


