from math import isqrt


def integer_cuberoot(n: int) -> int:
    lo, hi = 0, 1
    while hi * hi * hi <= n:
        hi *= 2
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if mid * mid * mid <= n:
            lo = mid
        else:
            hi = mid
    return lo


def solve() -> None:
    n = int(sys.stdin.readline())
    limit = integer_cuberoot(n)

    for d in range(1, limit + 1):
        if n % d != 0:
            continue

        q = n // d
        discriminant = 12 * q - 3 * d * d
        if discriminant < 0:
            continue

        root = isqrt(discriminant)
        if root * root != discriminant:
            continue

        numerator = root - 3 * d
        if numerator <= 0 or numerator % 6 != 0:
            continue

        y = numerator // 6
        x = y + d
        if y > 0 and x * x * x - y * y * y == n:
            print(x, y)
            return

    print(-1)


if __name__ == "__main__":
    solve()

import sys
from collections import deque


class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        self.g[fr].append([to, cap, len(self.g[to])])
        self.g[to].append([fr, 0, len(self.g[fr]) - 1])

    def max_flow(self, s, t, limit=None):
        flow = 0
        n = self.n

        while limit is None or flow < limit:
            level = [-1] * n
            level[s] = 0
            q = deque([s])
            while q:
                v = q.popleft()
                for to, cap, rev in self.g[v]:
                    if cap > 0 and level[to] < 0:
                        level[to] = level[v] + 1
                        q.append(to)

            if level[t] < 0:
                break

            it = [0] * n

            def dfs(v, f):
                if v == t:
                    return f
                while it[v] < len(self.g[v]):
                    e = self.g[v][it[v]]
                    to, cap, rev = e
                    if cap > 0 and level[v] + 1 == level[to]:
                        pushed = dfs(to, min(f, cap))
                        if pushed:
                            e[1] -= pushed
                            self.g[to][rev][1] += pushed
                            return pushed
                    it[v] += 1
                return 0

            while limit is None or flow < limit:
                pushed = dfs(s, (limit - flow) if limit is not None else 10**18)
                if pushed == 0:
                    break
                flow += pushed

        return flow


def main():
    input = sys.stdin.readline
    n, m, k = map(int, input().split())
    edges = []
    for _ in range(m):
        u, v = map(int, input().split())
        edges.append((u - 1, v - 1))

    def feasible(d):
        if d == 0:
            return True

        variable_count = n * d
        source = variable_count
        sink = variable_count + 1
        dinic = Dinic(variable_count + 2)

        inf = m + 1

        def node(v, level):
            return v * d + level

        # Enforce d_v >= i+2 => d_v >= i+1.
        for v in range(n):
            for i in range(d - 1):
                dinic.add_edge(node(v, i + 1), node(v, i), inf)

        # For every original edge u -> v:
        # d_v >= i+2 implies d_u >= i+1.
        for u, v in edges:
            for i in range(d - 1):
                dinic.add_edge(node(v, i + 1), node(u, i), inf)

        # A finite cut edge counts an original edge crossing upward
        # at the corresponding level.
        for u, v in edges:
            for i in range(d):
                dinic.add_edge(node(v, i), node(u, i), 1)

        # d_1 = 0: all positive-level variables of vertex 1 are false.
        for i in range(d):
            dinic.add_edge(node(0, i), sink, inf)

        # d_N >= d: all level variables of vertex N are true.
        for i in range(d):
            dinic.add_edge(source, node(n - 1, i), inf)

        return dinic.max_flow(source, sink, k + 1) <= k

    low, high = 0, n
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(low)


if __name__ == "__main__":
    main()

import sys


class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, value):
        while i <= self.n:
            self.bit[i] += value
            i += i & -i

    def sum(self, i):
        result = 0
        while i > 0:
            result += self.bit[i]
            i -= i & -i
        return result


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    p = data[1:]

    fenwick = Fenwick(n)
    answer = 0

    for j, x in enumerate(p, 1):
        previous_not_greater = fenwick.sum(x)
        greater_count = (j - 1) - previous_not_greater

        # The element crosses boundaries j-1, j-2, ..., j-greater_count.
        answer += greater_count * (2 * j - greater_count - 1) // 2
        fenwick.add(x, 1)

    print(answer)


