        queue = deque([start])
        component = []
        valid = True

        while queue:
            u = queue.popleft()
            component.append(u)

            for v, z in adj[u]:
                expected = potential[u] ^ z
                if potential[v] == -1:
                    potential[v] = expected
                    queue.append(v)
                elif potential[v] != expected:
                    valid = False
                    break

            if not valid:
                break

        if not valid:
            print(-1)
            return

