from collections import deque


def bfs(graph, root):
    n = len(graph)
    dist = [-1] * n
    parent = [-1] * n
    order = []

    dist[root] = 0
    q = deque([root])

    while q:
        v = q.popleft()
        order.append(v)
        for to in graph[v]:
            if dist[to] == -1:
                dist[to] = dist[v] + 1
                parent[to] = v
                q.append(to)

    return dist, parent, order


def solve():
    input = sys.stdin.readline

    n, m, s, t = map(int, input().split())
    s -= 1
    t -= 1

    graph = [[] for _ in range(n)]
    edges = []

    for _ in range(m):
