import sys

MOD = 998244353


def make_row(values, s):
    mat = [0] * (s * s)
    for k in range(s):
        cur = values[k]
        mat[k * s + k] = cur
        for j in range(k + 1, s):
            cur = cur * values[j] % MOD
            mat[j * s + k] = cur
    return mat


def mat_mul(a, b, s):
    c = [0] * (s * s)
    for i in range(s):
        ib = i * s
        for k in range(i + 1):
            x = a[ib + k]
            if x:
                kb = k * s
                for j in range(k + 1):
                    c[ib + j] = (c[ib + j] + x * b[kb + j]) % MOD
    return c


def solve_small(H, W, grid, queries):
    transposed = H < W
    if transposed:
        length, width = W, H
    else:
        length, width = H, W

    size = 1
    while size < length:
        size <<= 1

    identity = [0] * (width * width)
    for i in range(width):
        identity[i * width + i] = 1

    tree = [identity[:] for _ in range(2 * size)]

    for r in range(length):
        vals = [0] * width
        if transposed:
            for c in range(width):
                vals[c] = grid[c * W + r]
        else:
            base = r * W
            for c in range(width):
                vals[c] = grid[base + c]
        tree[size + r] = make_row(vals, width)

    for p in range(size - 1, 0, -1):
        tree[p] = mat_mul(tree[p << 1 | 1], tree[p << 1], width)

    answers = []

    for _, value, r, c in queries:
        grid[r * W + c] = value

        rr = c if transposed else r
        vals = [0] * width
        if transposed:
            for j in range(width):
                vals[j] = grid[j * W + rr]
        else:
            base = rr * W
            for j in range(width):
                vals[j] = grid[base + j]

        p = size + rr
        tree[p] = make_row(vals, width)
        p >>= 1
        while p:
            tree[p] = mat_mul(tree[p << 1 | 1], tree[p << 1], width)
            p >>= 1

        answers.append(str(tree[1][(width - 1) * width] % MOD))

    return answers


def solve_block(H, W, grid, queries):
    n = H * W
    q = len(queries)
    block_size = 320
    answers = []

    for block_start in range(0, q, block_size):
        block_end = min(q, block_start + block_size)

        r1, c1 = H, W
        r2, c2 = -1, -1
        for k in range(block_start, block_end):
            r, c, _ = queries[k]
            if r < r1:
                r1 = r
            if r > r2:
                r2 = r
            if c < c1:
                c1 = c
            if c > c2:
                c2 = c

        height = r2 - r1 + 1
        width = c2 - c1 + 1

        forward = [0] * W
        top = [0] * width
        left = [0] * height
        total = 0

        for r in range(H):
            base = r * W
            for c in range(W):
                if r == 0 and c == 0:
                    forward[c] = grid[0]
                else:
                    ways = 0
                    if r:
                        ways += forward[c]
                    if c:
                        ways += forward[c - 1]
                    forward[c] = grid[base + c] * ways % MOD

            if r == r1 - 1:
                for j in range(width):
                    top[j] = forward[c1 + j]
            if r1 <= r <= r2 and c1:
                left[r - r1] = forward[c1 - 1]

            if r == H - 1:
                total = forward[W - 1]

        bottom = [0] * width
        right = [0] * height
        backward = [0] * W

        for r in range(H - 1, -1, -1):
            base = r * W
            for c in range(W - 1, -1, -1):
                if r == H - 1 and c == W - 1:
                    backward[c] = grid[n - 1]
                else:
                    ways = 0
                    if r + 1 < H:
                        ways += backward[c]
                    if c + 1 < W:
                        ways += backward[c + 1]
                    backward[c] = grid[base + c] * ways % MOD

            if r == r2 + 1:
                for j in range(width):
                    bottom[j] = backward[c1 + j]
            if r1 <= r <= r2 and c2 + 1 < W:
                right[r - r1] = backward[c2 + 1]

        inside = [[0] * width for _ in range(height)]

        def rebuild(si, sj):
            for i in range(si, height):
                rr = r1 + i
                row = inside[i]
                base = rr * W

                for j in range(sj, width):
                    cc = c1 + j

                    if rr == 0 and cc == 0:
                        row[j] = grid[0]
                        continue

                    ways = 0
                    if i:
                        ways += inside[i - 1][j]
                    elif r1:
                        ways += top[j]

                    if j:
                        ways += row[j - 1]
                    elif c1:
                        ways += left[i]

                    row[j] = grid[base + cc] * ways % MOD

        rebuild(0, 0)

        def crossing():
            result = 0

            if r2 + 1 < H:
                last = inside[-1]
                for j in range(width):
                    result += last[j] * bottom[j]

            if c2 + 1 < W:
                j = width - 1
                for i in range(height):
                    result += inside[i][j] * right[i]

            if r2 == H - 1 and c2 == W - 1:
                result += inside[-1][-1]

            return result % MOD

        old_crossing = crossing()

        for k in range(block_start, block_end):
            r, c, value = queries[k]
            grid[r * W + c] = value

            rebuild(r - r1, c - c1)
            new_crossing = crossing()

            answers.append(str((total - old_crossing + new_crossing) % MOD))

    return answers


def solve():
    data = sys.stdin.buffer.read().split()
    it = iter(data)

    H = int(next(it))
    W = int(next(it))
    grid = [int(next(it)) for _ in range(H * W)]

    Q = int(next(it))
    r = int(next(it)) - 1
    c = int(next(it)) - 1

    queries = []
    for _ in range(Q):
        direction = next(it)
        value = int(next(it))

        if direction == b"L":
            c -= 1
        elif direction == b"R":
            c += 1
        elif direction == b"U":
            r -= 1
        else:
            r += 1

        queries.append((r, c, value))

    if min(H, W) <= 6:
        answers = solve_small(H, W, grid, queries)
    else:
        answers = solve_block(H, W, grid, queries)

    sys.stdout.write("\n".join(answers))


if __name__ == "__main__":
    solve()

import sys
from bisect import bisect_right
from array import array


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, m = data[0], data[1]
    left = [0] * m
    right = [0] * m

    p = 2
    for i in range(m):
        left[i] = data[p]
        right[i] = data[p + 1]
        p += 2

    order = sorted(range(m), key=lambda i: (left[i], i))
    sorted_left = [left[i] for i in order]

    top1 = [-1] * m
    top2 = [-1] * m
    top3 = [-1] * m

    a = b = c = -1
    for pos, idx in enumerate(order):
        ri = right[idx]
        if a == -1 or ri > right[a]:
            c, b, a = b, a, idx
        elif b == -1 or ri > right[b]:
            c, b = b, idx
        elif c == -1 or ri > right[c]:
            c = idx

        top1[pos] = a
        top2[pos] = b
        top3[pos] = c

    coords = {1, n + 1}
    coords.update(left)
    coords.update(r + 1 for r in right)
    coords = sorted(coords)
    state_id = {x: i for i, x in enumerate(coords)}
    s = len(coords)

    state_top = array("i", [-1]) * s
    state_second = array("i", [-1]) * s

    for si, pos in enumerate(coords):
        q = bisect_right(sorted_left, pos) - 1
        if q >= 0:
            state_top[si] = top1[q]
            state_second[si] = top2[q]

    ordinary = array("i", [-1]) * s
    second = array("i", [-1]) * s

    for si, pos in enumerate(coords):
        t = state_top[si]
        if t != -1 and right[t] >= pos:
            ordinary[si] = state_id[right[t] + 1]

        t = state_second[si]
        if t != -1 and right[t] >= pos:
            second[si] = state_id[right[t] + 1]

    log = max(1, s.bit_length())

    ordinary_jump = [ordinary]
    for _ in range(1, log):
        prev = ordinary_jump[-1]
        cur = array("i", [-1]) * s
        for v in range(s):
            mid = prev[v]
            if mid != -1:
                cur[v] = prev[mid]
        ordinary_jump.append(cur)

    second_jump = [second]
    uniform_top = [array("i", [-1]) * s]

    for v in range(s):
        if second[v] != -1 and state_top[v] != -1:
            uniform_top[0][v] = state_top[v]

    for _ in range(1, log):
        prev_jump = second_jump[-1]
        prev_uniform = uniform_top[-1]
        cur_jump = array("i", [-1]) * s
        cur_uniform = array("i", [-1]) * s

        for v in range(s):
            mid = prev_jump[v]
            if mid != -1:
                cur_jump[v] = prev_jump[mid]
                x = prev_uniform[v]
                y = prev_uniform[mid]
                if x != -1 and x == y:
                    cur_uniform[v] = x

        second_jump.append(cur_jump)
        uniform_top.append(cur_uniform)

    def count_global(start, end):
        if start > end:
            return 0

        v = state_id[start]
        result = 0

        for k in range(log - 1, -1, -1):
            nv = ordinary_jump[k][v]
            if nv != -1 and coords[nv] <= end:
                v = nv
                result += 1 << k

        if coords[v] <= end:
            nv = ordinary_jump[0][v]
            if nv == -1:
                return None
            result += 1

        return result

    def count_without(forbidden, start, end):
        if start > end:
            return 0

        v = state_id[start]
        result = 0

        while coords[v] <= end:
            if state_top[v] != forbidden:
                tail = count_global(coords[v], end)
                if tail is None:
                    return None
                return result + tail

            for k in range(log - 1, -1, -1):
                nv = second_jump[k][v]
                if (
                    nv != -1
                    and uniform_top[k][v] == forbidden
                    and coords[nv] <= end
                ):
                    v = nv
                    result += 1 << k

            if coords[v] > end:
                return result

            nv = second[v]
            if nv == -1:
                return None
            v = nv
            result += 1

        return result

    def best_interval(pos, forbidden1=-1, forbidden2=-1):
        q = bisect_right(sorted_left, pos) - 1
        if q < 0:
            return -1

        for idx in (top1[q], top2[q], top3[q]):
            if idx != -1 and idx != forbidden1 and idx != forbidden2:
                return idx
        return -1

    def cover(start, end, forbidden1=-1, forbidden2=-1):
        if start > end:
            return []

        pos = start
        result = []

        while pos <= end:
            idx = best_interval(pos, forbidden1, forbidden2)
            if idx == -1 or right[idx] < pos:
                return None
            result.append(idx)
            pos = right[idx] + 1

        return result

    best_cost = None
    best_twos = []
    best_ones = []

    def consider(cost, twos, ones):
        nonlocal best_cost, best_twos, best_ones
        if best_cost is None or cost < best_cost:
            best_cost = cost
            best_twos = twos
            best_ones = ones

    only_ones = count_global(1, n)
    if only_ones is not None:
        consider(only_ones, [], [])

    for i in range(m):
        covered = count_without(i, left[i], right[i])
        if covered is not None:
            consider(1 + covered, [i], [])

    max_left_idx = max(range(m), key=lambda i: left[i])
    min_right_idx = min(range(m), key=lambda i: right[i])

    if max_left_idx != min_right_idx:
        residual_left = max(left[max_left_idx], left[min_right_idx])
        residual_right = min(right[max_left_idx], right[min_right_idx])

        if residual_left > residual_right:
            consider(2, [max_left_idx, min_right_idx], [])
        else:
            ones = cover(
                residual_left,
                residual_right,
                max_left_idx,
                min_right_idx,
            )
            if ones is not None:
                consider(
                    2 + len(ones),
                    [max_left_idx, min_right_idx],
                    ones,
                )

    if best_cost is None:
        print(-1)
        return

    if len(best_twos) == 1 and not best_ones:
        idx = best_twos[0]
        best_ones = cover(left[idx], right[idx], idx)
        if best_ones is None:
            print(-1)
            return
    elif len(best_twos) == 0 and not best_ones:
        best_ones = cover(1, n)
        if best_ones is None:
            print(-1)
            return

    operations = [0] * m
    for idx in best_twos:
        operations[idx] = 2
    for idx in best_ones:
        if operations[idx] == 0:
            operations[idx] = 1

    print(best_cost)
    print(*operations)


