        for i in range(k):
            if 2 * a[i] > a[n - k + i]:
                return False
        return True

    low = 0
    high = n // 2 + 1

    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(low)


if __name__ == "__main__":
    solve()

from bisect import bisect_right
from typing import List


class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)

        ordered = sorted(
            (left, right, weight, index)
            for index, (left, right, weight) in enumerate(intervals)
        )

        starts = [left for left, _, _, _ in ordered]

        # Intervals must start strictly after the current interval ends.
        next_pos = [
            bisect_right(starts, ordered[i][1])
            for i in range(n)
        ]

        # dp_score[i][k] and dp_indices[i][k] represent the best result
        # using at most k intervals from sorted position i onward.
        dp_score = [[0] * 5 for _ in range(n + 1)]
        dp_indices = [[()] * 5 for _ in range(n + 1)]

        for i in range(n - 1, -1, -1):
            _, _, weight, original_index = ordered[i]
            nxt = next_pos[i]

            for k in range(1, 5):
                # Skip the current interval.
                best_score = dp_score[i + 1][k]
                best_indices = dp_indices[i + 1][k]

                # Take the current interval.
                take_score = weight + dp_score[nxt][k - 1]
                take_indices = tuple(
                    sorted((original_index,) + dp_indices[nxt][k - 1])
                )

                if (
                    take_score > best_score
                    or (
                        take_score == best_score
                        and take_indices < best_indices
                    )
                ):
                    best_score = take_score
                    best_indices = take_indices

                dp_score[i][k] = best_score
                dp_indices[i][k] = best_indices

        return list(dp_indices[0][4])

from typing import List


class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        NEG = -10**30

        # A summary is:
        # (length, total_sum, best_prefix, best_suffix, best_subarray)
        EMPTY = (0, 0, NEG, NEG, NEG)

        def merge(a, b):
            if a[0] == 0:
                return b
            if b[0] == 0:
                return a

            length = a[0] + b[0]
            total = a[1] + b[1]
            prefix = max(a[2], a[1] + b[2])
            suffix = max(b[3], b[1] + a[3])
            best = max(a[4], b[4], a[3] + b[2])
            return (length, total, prefix, suffix, best)

        size = 1
        while size < n:
            size <<= 1

        tree = [EMPTY] * (2 * size)

        for i, value in enumerate(nums):
            tree[size + i] = (1, value, value, value, value)

        for i in range(size - 1, 0, -1):
            tree[i] = merge(tree[i << 1], tree[i << 1 | 1])

        def query(left: int, right: int):
            """Return the summary of nums[left:right]."""
            if left >= right:
                return EMPTY

            left += size
            right += size
            left_result = EMPTY
            right_result = EMPTY

            while left < right:
                if left & 1:
                    left_result = merge(left_result, tree[left])
                    left += 1
                if right & 1:
                    right -= 1
                    right_result = merge(tree[right], right_result)
                left >>= 1
                right >>= 1

            return merge(left_result, right_result)

        positions = {}
        for i, value in enumerate(nums):
            positions.setdefault(value, []).append(i)

        answer = tree[1][4]  # No deletion.

        for value, occurrence_positions in positions.items():
            if len(occurrence_positions) == n:
                # Deleting this value would leave an empty array.
                continue

            combined = EMPTY
            previous_end = 0

            for position in occurrence_positions:
                # This block contains no occurrence of 'value'.
                combined = merge(combined, query(previous_end, position))
                previous_end = position + 1

            combined = merge(combined, query(previous_end, n))

            if combined[0] > 0:
                answer = max(answer, combined[4])

        return answer

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def feasible(limit: int) -> bool:
            if limit == 1:
                flips_start_zero = 0
                flips_start_one = 0

                for i, ch in enumerate(s):
                    expected_zero = '0' if i % 2 == 0 else '1'
                    expected_one = '1' if i % 2 == 0 else '0'

                    if ch != expected_zero:
                        flips_start_zero += 1
                    if ch != expected_one:
                        flips_start_one += 1

                return min(flips_start_zero, flips_start_one) <= numOps

            required = 0
            i = 0

            while i < n:
                j = i + 1
                while j < n and s[j] == s[i]:
                    j += 1

                required += (j - i) // (limit + 1)
                if required > numOps:
                    return False

                i = j

            return True

        left, right = 1, n

        while left < right:
            mid = (left + right) // 2
            if feasible(mid):
                right = mid
            else:
                left = mid + 1

        return left

import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    a = data[1:1 + n]
    total = (n + 1) * sum(a)

    answer = total
    max_sum = 2 * max(a)
    modulus = 2

    while modulus <= max_sum:
        groups = {}
        for value in a:
            r = value % modulus
            if r in groups:
                groups[r][0] += 1
                groups[r][1] += value
            else:
                groups[r] = [1, value]

        divisible_sum = 0

        for r, (count, value_sum) in groups.items():
            complement = (-r) % modulus
            if complement not in groups:
                continue

            if r == complement:
                # All unordered pairs, including diagonal pairs, inside one class.
                divisible_sum += (count + 1) * value_sum
            elif r < complement:
                other_count, other_sum = groups[complement]
                divisible_sum += value_sum * other_count + other_sum * count

        # Every term counted in divisible_sum is divisible by modulus.
        answer -= divisible_sum // modulus
        modulus <<= 1

    print(answer)


if __name__ == "__main__":
    solve()

import sys
from bisect import bisect_left


def build_required_sequence(perm, balls, x, n):
    cycle = []
    cur = x
    while True:
        cycle.append(cur)
        cur = perm[cur]
        if cur == x:
            break

    pos = [-1] * n
    for i, v in enumerate(cycle):
        pos[v] = i

    first = len(cycle)
    for i, has_ball in enumerate(balls):
        if has_ball:
            if pos[i] == -1:
                return None
            if pos[i] != 0:
                first = min(first, pos[i])

    if first == len(cycle):
        return []

    return cycle[first:]


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)

    n = next(it)
    x = next(it) - 1
    a = [next(it) for _ in range(n)]
    b = [next(it) for _ in range(n)]
    p = [next(it) - 1 for _ in range(n)]
    q = [next(it) - 1 for _ in range(n)]

    red = build_required_sequence(p, a, x, n)
    if red is None:
        print(-1)
        return

    blue = build_required_sequence(q, b, x, n)
    if blue is None:
        print(-1)
        return

    blue_pos = [-1] * n
    for i, v in enumerate(blue):
        blue_pos[v] = i

    tails = []
    for v in red:
        z = blue_pos[v]
        if z != -1:
            k = bisect_left(tails, z)
            if k == len(tails):
                tails.append(z)
            else:
                tails[k] = z

    lcs = len(tails)
    print(len(red) + len(blue) - lcs)


if __name__ == "__main__":
    main()

import sys
from array import array


def solve():
    input = sys.stdin.buffer.readline
    n = int(input())
    a = list(map(int, input().split()))

    nxt = [-1] * n
    stack = []
    for i in range(n - 1, -1, -1):
        while stack and a[stack[-1]] < a[i]:
            stack.pop()
        if stack:
            nxt[i] = stack[-1]
        stack.append(i)

    prv = [-1] * n
    stack.clear()
    for i in range(n):
        while stack and a[stack[-1]] < a[i]:
            stack.pop()
        if stack:
            prv[i] = stack[-1]
        stack.append(i)

    levels = n.bit_length()
    rjump = [array("i", nxt)]
    ljump = [array("i", prv)]
    del nxt, prv

    for _ in range(1, levels):
        old_r = rjump[-1]
        old_l = ljump[-1]
        cur_r = array("i", [-1]) * n
        cur_l = array("i", [-1]) * n

        for i in range(n):
            q = old_r[i]
            if q >= 0:
                cur_r[i] = old_r[q]

            q = old_l[i]
            if q >= 0:
                cur_l[i] = old_l[q]

        rjump.append(cur_r)
        ljump.append(cur_l)

    pref = [0] * (n + 1)
    total = 0
    for i, x in enumerate(a):
        total += x
        pref[i + 1] = total

    def first_at_least(pos, value):
        if pos >= n:
            return n
        if a[pos] >= value:
            return pos

        cur = pos
        for k in range(levels - 1, -1, -1):
            q = rjump[k][cur]
            if q >= 0 and a[q] < value:
                cur = q

        q = rjump[0][cur]
        return n if q < 0 else q

    def last_at_least(pos, value):
        if pos < 0:
            return -1
        if a[pos] >= value:
            return pos

        cur = pos
        for k in range(levels - 1, -1, -1):
            q = ljump[k][cur]
            if q >= 0 and a[q] < value:
                cur = q

        q = ljump[0][cur]
        return -1 if q < 0 else q

    ans = [0] * n

    for start in range(n):
        left = start
        right = start
        size = a[start]

        while True:
            changed = False

            if left > 0:
                blocker = last_at_least(left - 1, size)
                if blocker < left - 1:
                    size += pref[left] - pref[blocker + 1]
                    left = blocker + 1
                    changed = True

            if right + 1 < n:
                blocker = first_at_least(right + 1, size)
                if blocker > right + 1:
                    size += pref[blocker] - pref[right + 1]
                    right = blocker - 1
                    changed = True

            if not changed:
                break

        ans[start] = size

    sys.stdout.write(" ".join(map(str, ans)))


if __name__ == "__main__":
    solve()

from typing import List


class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))
        size = [1] * n

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra = find(a)
            rb = find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

        index = {value: i for i, value in enumerate(nums)}
        representative = [-1] * (threshold + 1)

        for value in nums:
            if value > threshold:
                continue

            current = index[value]
            for multiple in range(value, threshold + 1, value):
                previous = representative[multiple]
                if previous != -1:
                    union(current, previous)
                representative[multiple] = current

        return len({find(i) for i in range(n)})
